-- Drops the retired v1 story pipeline: its tables, the stories and themes FTS
-- indexes, and the story columns on articles, deliveries, feedback and llm_calls.
-- Generated by drizzle-kit, then reordered and edited by hand:
--
-- * D1 enforces foreign keys and ignores `PRAGMA foreign_keys = OFF`, so the
--   rebuilds run under `defer_foreign_keys`. Dropping the old copy of a parent
--   table (articles, deliveries, llm_calls) counts a violation for every child
--   row until the new copy is renamed into place. Turning the pragma off at the
--   end clears that count, and nothing dangles by then.
-- * Every dropped column sits in a foreign key, so SQLite cannot
--   `ALTER TABLE ... DROP COLUMN` it: each of the four tables is rebuilt.
-- * Child tables go before their parents, and the kept tables are rebuilt
--   without their story columns before stories itself goes, so no row ever
--   points at a dropped table.
-- * The articles rebuild drops the articles_fts triggers. They are recreated
--   at the end, as in 0001_fts.sql.

PRAGMA defer_foreign_keys = on;--> statement-breakpoint

-- FTS over tables that go. Their sync triggers go first: every ALTER TABLE
-- RENAME below re-checks the whole schema and fails on a trigger whose FTS
-- table no longer exists.
DROP TRIGGER `stories_fts_ai`;--> statement-breakpoint
DROP TRIGGER `stories_fts_ad`;--> statement-breakpoint
DROP TRIGGER `stories_fts_au`;--> statement-breakpoint
DROP TRIGGER `themes_fts_ai`;--> statement-breakpoint
DROP TRIGGER `themes_fts_ad`;--> statement-breakpoint
DROP TRIGGER `themes_fts_au`;--> statement-breakpoint
DROP TABLE `stories_fts`;--> statement-breakpoint
DROP TABLE `themes_fts`;--> statement-breakpoint

-- v1 tables that nothing kept references: children before parents.
DROP TABLE `story_entities`;--> statement-breakpoint
DROP TABLE `story_themes`;--> statement-breakpoint
DROP TABLE `theme_events`;--> statement-breakpoint
DROP TABLE `story_vulns`;--> statement-breakpoint
DROP TABLE `facts`;--> statement-breakpoint
DROP TABLE `signals`;--> statement-breakpoint
DROP TABLE `follows`;--> statement-breakpoint
DROP TABLE `match_log`;--> statement-breakpoint
DROP TABLE `gate_log`;--> statement-breakpoint
DROP TABLE `briefs`;--> statement-breakpoint

-- articles without origin_id and story_id. v2 keeps wire copies in event_articles.origin_article_id.
CREATE TABLE `__new_articles` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`source_id` integer NOT NULL,
	`guid` text NOT NULL,
	`canonical_url` text NOT NULL,
	`domain` text NOT NULL,
	`title` text NOT NULL,
	`snippet` text,
	`lang` text,
	`published_at` integer NOT NULL,
	`fetched_at` integer NOT NULL,
	`embedded_at` integer,
	`fulltext_r2_key` text,
	`cve_ids_json` text,
	`entities_json` text,
	`is_promotional` integer DEFAULT false NOT NULL,
	`is_aggregator` integer DEFAULT false NOT NULL,
	`injection_suspect` integer DEFAULT false NOT NULL,
	FOREIGN KEY (`source_id`) REFERENCES `sources`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
INSERT INTO `__new_articles`("id", "source_id", "guid", "canonical_url", "domain", "title", "snippet", "lang", "published_at", "fetched_at", "embedded_at", "fulltext_r2_key", "cve_ids_json", "entities_json", "is_promotional", "is_aggregator", "injection_suspect") SELECT "id", "source_id", "guid", "canonical_url", "domain", "title", "snippet", "lang", "published_at", "fetched_at", "embedded_at", "fulltext_r2_key", "cve_ids_json", "entities_json", "is_promotional", "is_aggregator", "injection_suspect" FROM `articles`;--> statement-breakpoint
DROP TABLE `articles`;--> statement-breakpoint
ALTER TABLE `__new_articles` RENAME TO `articles`;--> statement-breakpoint
CREATE UNIQUE INDEX `articles_canonicalUrl_unique` ON `articles` (`canonical_url`);--> statement-breakpoint
CREATE INDEX `articles_published_idx` ON `articles` (`published_at`);--> statement-breakpoint
CREATE UNIQUE INDEX `articles_source_guid_uq` ON `articles` (`source_id`,`guid`);--> statement-breakpoint

