	FOREIGN KEY (`thread_id`) REFERENCES `threads`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`digest_date`) REFERENCES `digests`(`digest_date`) ON UPDATE no action ON DELETE no action
